export type IWorkerDefinition = {
	label: string;
	entry: string;
}

export type BultinLanguageWorker = 'css' | 'html' | 'json' | 'typescript';

export interface IMonacoEditorOptions {
	// ---cut-start---
	/**
	 * a subset of bultin language workers to enable
	 * @default ['css', 'html', 'json', 'typescript']
	 */
	// ---cut-end---
	languageWorkers?: BultinLanguageWorker[];
	customLanguageWorkers?: IWorkerDefinition[];
	// ---cut-start---
	/**
	 * Override the public path from which files generated by this plugin will be served.
	 * This wins out over Webpack's dynamic runtime path and can be useful to avoid attempting to load workers cross-
	 * origin when using a CDN for other static resources.
	 * Use e.g. '/' if you want to load your resources from the current origin.
	 */
	// ---cut-end---
	publicPath?: string;
	customDistPath?: (root: string, buildOutDir: string, base: string) => string;
	forceBuildCDN?: boolean;
	// ---cut-start---
	/**
	 * define a global `monaco` object or not
	 * @since `monaco-editor` v0.22.0
	 * @see [change log](https://github.com/microsoft/monaco-editor/blob/main/CHANGELOG.md#0220-29012021)
	 * @default false
	 */
	// ---cut-end---
	globalAPI?: boolean;
}

